// 01 - Affinity: a pinned thread stays on its core; affinity can change.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  volatile unsigned g_seen_core[ncpu];

  void*
  report_core (void* arg)
  {
    const unsigned slot = from_arg (arg);
    // Look twice, around a sleep: a pinned thread comes back on its core.
    unsigned core = mtp_board::cpu_id ();
    sysclock.sleep_for (ms (5));
    if (mtp_board::cpu_id () != core)
      {
        core = 0xff;
      }
    store (g_seen_core[slot], core);
    return nullptr;
  }
} // namespace

mt::static_suite suite_affinity{
  "01 - Affinity", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("the runner is on core 0", [] (auto& t) {
      t.expect (mt::eq (mtp_board::cpu_id (), 0u)) << "release_cores () pinned it";
    });

    ts.test ("a thread pinned to a core runs on that core", [] (auto& t) {
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          store (g_seen_core[core], 0xeeu);
          threads[core] = spawn ("mtp-pin", report_core, as_arg (core),
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      for (unsigned core = 0; core < ncpu; ++core)
        {
          t.expect (mt::eq (load (g_seen_core[core]), core))
              << fmt ("pinned to core %u, and stayed there", core);
        }
    });

    ts.test ("affinity can be changed at run time", [] (auto& t) {
      thread& self = this_thread::thread ();
      self.cpu_affinity (1u << last);
      sysclock.sleep_for (ms (2));
      const unsigned on = mtp_board::cpu_id ();
      self.cpu_affinity (1u << 0);
      sysclock.sleep_for (ms (2));
      t.expect (mt::eq (on, last)) << fmt ("moved to core %u", last);
      t.expect (mt::eq (mtp_board::cpu_id (), 0u)) << "and back to core 0";
      t.expect (mt::eq (static_cast<unsigned> (self.cpu_affinity ()), 1u))
          << "cpu_affinity () reads back";
    });
  }
};
